#!/usr/bin/env node
// Keeps this fork of get-bb/bb `plugins/thread-list` in step with upstream.
// See docs/fork.md. The pin lives in upstream.json.
//
//   node scripts/fork-upstream.mjs vendor [--bb <checkout>]
//     Rewrites the fork's generated files from upstream at the pin, the way
//     upstream's own fork check does (scripts/check-plugin-forks.mjs): writes
//     the component registry items the sources import, regenerates
//     package.json and tsconfig.json from upstream's with
//     scripts/lib/plugin-fork.mjs, then applies FORK_MANIFEST below.
//
//   node scripts/fork-upstream.mjs merge <commit> [--bb <checkout>]
//     Three-way merges every upstream plugin file from the pin to <commit>
//     into the fork (git merge-file), moves the pin, and runs vendor.
//
// Without --bb, a sparse blobless clone of the upstream repository is made in
// a temporary directory.
import { execFileSync } from "node:child_process";
import {
  existsSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  readdirSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const pinPath = join(root, "upstream.json");
const pin = JSON.parse(readFileSync(pinPath, "utf8"));

// The fork's identity. Everything else in package.json comes from upstream.
const FORK_MANIFEST = {
  name: "bb-plugin-inbox",
  description:
    "A fork of bb's sidebar thread list that adds an Inbox tab for triaging agent work.",
  bb: {
    name: "Inbox",
    description:
      "A fork of bb's sidebar thread list that adds an Inbox tab for triaging agent work.",
  },
  scripts: { build: "bb plugin build ." },
  dependencies: { diff: "^8.0.2" },
};

// Fork-owned sources tsconfig.json includes besides upstream's.
const FORK_TSCONFIG_INCLUDE = ["fork.test.ts", "server/**/*.ts"];

// Upstream paths that live elsewhere in the fork.
const PATH_RENAMES = {
  "skills/thread-list/SKILL.md": "skills/inbox/SKILL.md",
};

// Generated by `vendor`, never merged.
const GENERATED = new Set(["package.json", "tsconfig.json"]);

const SPARSE_PATHS = [
  "/scripts/lib/plugin-fork.mjs",
  "/packages/plugin-build/package.json",
  "/packages/plugin-build/src/runtime-shims.mjs",
  "/packages/plugin-registry/package.json",
  "/packages/plugin-registry/r",
  "/apps/app/package.json",
];
const SKIPPED_DIRS = new Set(["node_modules", "dist", ".git", "scripts"]);

function git(cwd, ...args) {
  return execFileSync("git", args, { cwd, encoding: "utf8", maxBuffer: 1 << 28 });
}

function checkout(bbArg, commits) {
  if (bbArg !== undefined) return { dir: resolve(bbArg), cleanup: () => {} };
  const parent = mkdtempSync(join(tmpdir(), "bb-upstream-"));
  const dir = join(parent, "bb");
  git(parent, "clone", "-q", "--filter=blob:none", "--no-checkout", pin.repository, dir);
  git(dir, "sparse-checkout", "set", "--no-cone", `/${pin.pluginPath}`, ...SPARSE_PATHS);
  for (const commit of commits) git(dir, "fetch", "-q", "origin", commit);
  return { dir, cleanup: () => rmSync(parent, { recursive: true, force: true }) };
}

function showFile(bb, commit, path) {
  try {
    return execFileSync("git", ["show", `${commit}:${path}`], {
      cwd: bb,
      maxBuffer: 1 << 28,
    });
  } catch {
    return null;
  }
}

function listFiles(bb, commit, path) {
  return git(bb, "ls-tree", "-r", "--name-only", commit, "--", path)
    .split("\n")
    .filter(Boolean)
    .map((file) => relative(path, file));
}

function readJson(bb, commit, path) {
  const content = showFile(bb, commit, path);
  if (content === null) throw new Error(`${path} is missing at ${commit}`);
  return JSON.parse(content.toString("utf8"));
}

function sourceFiles(dir, skip) {
  const files = [];
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    if (SKIPPED_DIRS.has(entry.name)) continue;
    const path = join(dir, entry.name);
    if (entry.isDirectory()) files.push(...sourceFiles(path, skip));
    else if (/\.(?:tsx?|mts|cts)$/u.test(entry.name) && !skip.has(relative(root, path))) {
      files.push(path);
    }
  }
  return files;
}

function mergeManifest(base, overrides) {
  const merged = { ...base };
  for (const [key, value] of Object.entries(overrides)) {
    merged[key] =
      value !== null && typeof value === "object" && !Array.isArray(value)
        ? mergeManifest(base[key] ?? {}, value)
        : value;
  }
  return merged;
}

function writeJson(path, value) {
  writeFileSync(path, `${JSON.stringify(value, null, 2)}\n`);
}

async function vendor(bb) {
  git(bb, "checkout", "-q", pin.commit);
  const fork = await import(pathToFileURL(join(bb, "scripts/lib/plugin-fork.mjs")));
  const { SHIMMED_TYPE_PACKAGES } = await import(
    pathToFileURL(join(bb, "packages/plugin-build/src/runtime-shims.mjs"))
  );
  const registryDir = join(bb, "packages/plugin-registry/r");
  const registryItems = readdirSync(registryDir)
    .filter((name) => name.endsWith(".json") && name !== "index.json")
    .map((name) => JSON.parse(readFileSync(join(registryDir, name), "utf8")))
    .filter((item) => Array.isArray(item.files));
  const vendoredTargets = new Set(
    registryItems.flatMap((item) => item.files.map((file) => file.target)),
  );

  const specifiers = new Set();
  for (const file of sourceFiles(root, vendoredTargets)) {
    for (const specifier of fork.registryAliasImports(readFileSync(file, "utf8"))) {
      specifiers.add(specifier);
    }
  }
  const items = fork.registryItemsForImports(specifiers, registryItems);
  for (const item of items) {
    for (const file of item.files) {
      mkdirSync(dirname(join(root, file.target)), { recursive: true });
      writeFileSync(join(root, file.target), file.content);
    }
  }

  const registryManifest = JSON.parse(
    readFileSync(join(bb, "packages/plugin-registry/package.json"), "utf8"),
  );
  const appManifest = JSON.parse(readFileSync(join(bb, "apps/app/package.json"), "utf8"));
  const registryDependencies = fork.registryPackages(items, {
    shimmedPackages: new Set(SHIMMED_TYPE_PACKAGES),
    versions: {
      ...registryManifest.devDependencies,
      ...appManifest.devDependencies,
      ...appManifest.dependencies,
    },
  });
  const buildManifest = JSON.parse(
    readFileSync(join(bb, "packages/plugin-build/package.json"), "utf8"),
  );
  const upstreamManifest = readJson(bb, pin.commit, `${pin.pluginPath}/package.json`);
  const { manifest } = fork.forkPluginPackageJson(upstreamManifest, {
    sdkSpecifier: pin.pluginSdk,
    workspaceBinsByPackage: new Map([
      ["@bb/plugin-build", Object.keys(buildManifest.bin ?? {})],
    ]),
    registryDependencies,
  });
  writeJson(join(root, "package.json"), mergeManifest(manifest, FORK_MANIFEST));
  const tsconfig = fork.forkPluginTsconfig(
    readJson(bb, pin.commit, `${pin.pluginPath}/tsconfig.json`),
  );
  tsconfig.include = [...new Set([...tsconfig.include, ...FORK_TSCONFIG_INCLUDE])];
  writeJson(join(root, "tsconfig.json"), tsconfig);
  console.log(`vendored registry items: ${items.map((item) => item.name).join(", ")}`);
}

function merge(bb, target) {
  const forkPath = (file) => PATH_RENAMES[file] ?? file;
  const files = new Set([
    ...listFiles(bb, pin.commit, pin.pluginPath),
    ...listFiles(bb, target, pin.pluginPath),
  ]);
  const scratch = mkdtempSync(join(tmpdir(), "bb-merge-"));
  const conflicts = [];
  for (const file of [...files].sort()) {
    if (GENERATED.has(file)) continue;
    const base = showFile(bb, pin.commit, `${pin.pluginPath}/${file}`);
    const theirs = showFile(bb, target, `${pin.pluginPath}/${file}`);
    const ours = join(root, forkPath(file));
    if (base !== null && theirs !== null && base.equals(theirs)) continue;
    if (theirs === null) {
      if (existsSync(ours) && base !== null && readFileSync(ours).equals(base)) {
        rmSync(ours);
      } else if (existsSync(ours)) {
        conflicts.push(`${forkPath(file)} (deleted upstream, changed in the fork)`);
      }
      continue;
    }
    if (!existsSync(ours)) {
      mkdirSync(dirname(ours), { recursive: true });
      writeFileSync(ours, theirs);
      if (base !== null) conflicts.push(`${forkPath(file)} (deleted in the fork, changed upstream)`);
      continue;
    }
    const basePath = join(scratch, "base");
    const theirsPath = join(scratch, "theirs");
    writeFileSync(basePath, base ?? "");
    writeFileSync(theirsPath, theirs);
    try {
      execFileSync("git", [
        "merge-file",
        "-L", "fork",
        "-L", pin.commit.slice(0, 8),
        "-L", target.slice(0, 8),
        ours, basePath, theirsPath,
      ]);
    } catch (error) {
      if (typeof error.status === "number" && error.status > 0) {
        conflicts.push(forkPath(file));
      } else {
        throw error;
      }
    }
  }
  rmSync(scratch, { recursive: true, force: true });
  return conflicts;
}

const [command, ...rest] = process.argv.slice(2);
const bbIndex = rest.indexOf("--bb");
const bbArg = bbIndex === -1 ? undefined : rest[bbIndex + 1];
const positional = rest.filter((_, index) => index !== bbIndex && index !== bbIndex + 1);

if (command === "vendor") {
  const { dir, cleanup } = checkout(bbArg, [pin.commit]);
  try {
    await vendor(dir);
  } finally {
    cleanup();
  }
} else if (command === "merge" && positional.length === 1) {
  const { dir, cleanup } = checkout(bbArg, [pin.commit, positional[0]]);
  try {
    const target = git(dir, "rev-parse", positional[0]).trim();
    const conflicts = merge(dir, target);
    pin.commit = target;
    writeJson(pinPath, pin);
    await vendor(dir);
    if (conflicts.length > 0) {
      console.log(`conflicts to resolve:\n  ${conflicts.join("\n  ")}`);
      process.exitCode = 1;
    }
  } finally {
    cleanup();
  }
} else {
  console.error(
    "usage: node scripts/fork-upstream.mjs vendor [--bb <checkout>]\n" +
      "       node scripts/fork-upstream.mjs merge <commit> [--bb <checkout>]",
  );
  process.exitCode = 2;
}
